import{_ as l,a0 as e,w as p,s as x,I as s,x as i,a1 as a,A as n,ao as o}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const b=JSON.parse('{"title":"NixOS 系列 #2：如何在虚拟机上安装 NixOS？ | LCTT x X-CMD","titleTemplate":false,"description":"NixOS 系列 #2：如何在虚拟机上安装 NixOS？ | LCTT (202303) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"NixOS 系列 #2：如何在虚拟机上安装 NixOS？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"NixOS 系列 #2：如何在虚拟机上安装 NixOS？ | LCTT (202303) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202303/20230227.0 ⭐️⭐️ NixOS Series 2 How to Install NixOS on a Virtual Machine","title":"NixOS 系列 #2：如何在虚拟机上安装 NixOS？","tag":"202303","desc":""},"relativePath":"202303/20230227.0 ⭐️⭐️ NixOS Series 2 How to Install NixOS on a Virtual Machine.md","filePath":"[post].md"}'),u={name:"202303/20230227.0 ⭐️⭐️ NixOS Series 2 How to Install NixOS on a Virtual Machine.md"};function m(g,t,d,S,h,O){const r=e("Link");return p(),x("div",null,[t[28]||(t[28]=s("h1",{id:"nixos-系列-2-如何在虚拟机上安装-nixos",tabindex:"-1"},[i("NixOS 系列 #2：如何在虚拟机上安装 NixOS？ "),s("a",{class:"header-anchor",href:"#nixos-系列-2-如何在虚拟机上安装-nixos","aria-label":"Permalink to “NixOS 系列 #2：如何在虚拟机上安装 NixOS？”"},"​")],-1)),t[29]||(t[29]=s("p",null,"如果你可以在任何 Linux 发行版上使用 Nix 包管理器，为什么还要安装 NixOS？",-1)),t[30]||(t[30]=s("p",null,"在使用 NixOS 几天之前，我经常想知道同样的事情。",-1)),s("p",null,[t[1]||(t[1]=i("当我意识到这些好处后，我就写了这篇文章来帮助你了解 ",-1)),a(r,{href:"https://linux.cn/article-15606-1.html"},{default:n(()=>[...t[0]||(t[0]=[i("为什么你要考虑使用 NixOS",-1)])]),_:1}),t[2]||(t[2]=i("。如果你已经阅读了本系列的第一篇文章，那么你已经知道自己想要什么了。",-1))]),t[31]||(t[31]=s("p",null,"那么，如何开始呢？考虑到它对许多人来说可能是一种新体验，你应该用它替换日常使用的系统还是将其安装为虚拟机？",-1)),s("p",null,[t[4]||(t[4]=i("我建议在你想要将其替换为你的主要操作系统之前在虚拟机上使用 NixOS。这适用于你想尝试的任何新事物，特别是 ",-1)),a(r,{href:"https://itsfoss.com/advanced-linux-distros/"},{default:n(()=>[...t[3]||(t[3]=[i("先进的 Linux 发行版",-1)])]),_:1}),t[5]||(t[5]=i("，例如 NixOS。",-1))]),t[32]||(t[32]=o('<h3 id="使用-virtualbox-在-vm-中安装-nixos" tabindex="-1">使用 VirtualBox 在 VM 中安装 NixOS <a class="header-anchor" href="#使用-virtualbox-在-vm-中安装-nixos" aria-label="Permalink to “使用 VirtualBox 在 VM 中安装 NixOS”">​</a></h3><p>在本教程中，我将使用 VirtualBox。</p><p>如果你使用的是 Ubuntu 并且不关心是否拥有最新版本，那么可以使用一个命令安装 VirtualBox：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install virtualbox</span></span></code></pre></div><p>想要安装最新版本？你可以参考下面的指南：</p>',5)),s("blockquote",null,[s("p",null,[s("strong",null,[a(r,{href:"https://itsfoss.com/install-virtualbox-ubuntu/"},{default:n(()=>[...t[6]||(t[6]=[i("如何在 Ubuntu 上安装 VirtualBox（初学者教程）",-1)])]),_:1})])])]),s("p",null,[t[8]||(t[8]=i("如果你使用 Ubuntu 以外的任何发行版，你可以 ",-1)),a(r,{href:"https://www.virtualbox.org/wiki/Linux_Downloads"},{default:n(()=>[...t[7]||(t[7]=[i("按照其官方下载页面的下载说明进行操作",-1)])]),_:1}),t[9]||(t[9]=i("。",-1))]),t[33]||(t[33]=s("p",null,"成功安装 VirtualBox 后，让我们从第一步开始。",-1)),t[34]||(t[34]=s("h4",{id:"步骤-1-获-取nixos-的-iso-镜像",tabindex:"-1"},[i("步骤 1：获 取NixOS 的 ISO 镜像 "),s("a",{class:"header-anchor",href:"#步骤-1-获-取nixos-的-iso-镜像","aria-label":"Permalink to “步骤 1：获 取NixOS 的 ISO 镜像”"},"​")],-1)),s("p",null,[t[11]||(t[11]=i("你需要前往 NixOS ",-1)),a(r,{href:"https://nixos.org/download.html"},{default:n(()=>[...t[10]||(t[10]=[i("官方下载页面",-1)])]),_:1}),t[12]||(t[12]=i("。",-1))]),t[35]||(t[35]=o('<p>在 “NixOS: the Linux distribution” 部分，你会找到带有 GNOME 和 KDE 桌面的 ISO。</p><p>当然，也有最小化 ISO，但我建议使用两者之一（GNOME 和 KDE）：</p><p><img src="https://itsfoss.com/content/images/2023/02/Download-NixOS-ISO-file.png" alt="下载 NixOS ISO 文件"></p><p>对于本教程，我将使用 GNOME。</p><p>请记住，你可以选择 GNOME 和 KDE 两种<ruby>立付桌面环境<rt>Live Desktop</rt></ruby>。</p><p>而在安装过程中，你可以选择自己喜欢的桌面环境，包括 <strong>Xfce、Pantheon、Cinnamon、MATE</strong> 等等！</p><h4 id="步骤-2-在-virtualbox-中创建虚拟机" tabindex="-1">步骤 2：在 VirtualBox 中创建虚拟机 <a class="header-anchor" href="#步骤-2-在-virtualbox-中创建虚拟机" aria-label="Permalink to “步骤 2：在 VirtualBox 中创建虚拟机”">​</a></h4><p>打开 VirtualBox 并单击 “<ruby>新建<rt>New</rt></ruby>” 按钮添加新的虚拟机：</p><p><img src="https://itsfoss.com/content/images/2023/02/click-on-new-to-add-new-virtual-machine.png" alt="截图显示了如何点击新建按钮来添加新的虚拟机"></p><p>它将打开一个提示，要求你添加有关要添加的虚拟机的信息。</p><p>你可以先命名虚拟机：</p><ul><li>为你的虚拟机命名，以便你可以识别它是 NixOS 系统。所以我将其命名为 “NixOS”。</li><li>选择你刚刚下载的 ISO 镜像。</li><li>选择 “Linux” ISO 类型。</li><li>并在版本选择 “<ruby>其它 Linux（64 位）<rt>Other Linux (64-bit)</rt></ruby>”。</li></ul><p><img src="https://itsfoss.com/content/images/2023/02/Add-NixOS-ISO-to-VirtualBox.png" alt=""></p><p>选择所有内容后，单击 “<ruby>下一步<rt>Next</rt></ruby>” 按钮。</p><p>接下来，系统会要求你选择基本内存（RAM）、要分配给此虚拟机的处理器以及存储空间。</p><p>虽然 NixOS 没有提到官方要求，但我建议你为此安装至少拥有 <strong>4GB RAM</strong>、<strong>2-4 个处理器内核</strong>和 <strong>30GB 空间</strong>：</p><p><img src="https://itsfoss.com/content/images/2023/02/select-hardware-for-NixOS-VM-1.png" alt="选择 NixOS 虚拟机的硬件"></p><p>最后，它会显示你为此虚拟机所做选择的摘要：</p><p><img src="https://itsfoss.com/content/images/2023/02/summery-of-NixOS-VM-install.png" alt="NixOS 虚拟机 安装摘要"></p><p>如果一切正常，请单击 “<ruby>完成<rt>Finish</rt></ruby>” 按钮，它将为你创建一个 NixOS 虚拟机。</p><h4 id="步骤-3-安装-nixos" tabindex="-1">步骤 3：安装 NixOS <a class="header-anchor" href="#步骤-3-安装-nixos" aria-label="Permalink to “步骤 3：安装 NixOS”">​</a></h4><p>创建完虚拟机后，你为 NixOS 虚拟机指定的名称应该显示在 VirtualBox 的虚拟机列表中。</p><p>选择 “NixOS” 虚拟机并单击“开始”按钮：</p><p><img src="https://itsfoss.com/content/images/2023/02/start-the-NixOS-VM.png" alt="开始 NixOS 虚拟机"></p><p>它将启动 NixOS <ruby>立付桌面环境<rt>Live Desktop</rt></ruby>，以便你可以试用 Linux 发行版。</p><h5 id="选择安装语言" tabindex="-1">选择安装语言 <a class="header-anchor" href="#选择安装语言" aria-label="Permalink to “选择安装语言”">​</a></h5><p>启动进入 NixOS 后，安装程序将启动并要求你设置安装程序的首选语言：</p><p><img src="https://itsfoss.com/content/images/2023/02/1.-choose-the-language-of-NixOS-installer.png" alt="选择安装时的首选语言"></p><h5 id="选择地区和时区" tabindex="-1">选择地区和时区 <a class="header-anchor" href="#选择地区和时区" aria-label="Permalink to “选择地区和时区”">​</a></h5><p>接下来，选择你所在的地区和区域。如果你不知道这一点，你可以从地图上选择你的国家，它会为你设置。</p><p>选择区域和区域后，它还会选择系统的首选语言、数字和日期区域设置。</p><p>当然，你可以根据需要进行更改，但对于大多数用户而言，选定的选项就可以正常工作：</p><p><img src="https://itsfoss.com/content/images/2023/02/2.-choose-the-region-and-zone-for-NixOS.png" alt="选择地区和时区"></p><h5 id="选择键盘布局" tabindex="-1">选择键盘布局 <a class="header-anchor" href="#选择键盘布局" aria-label="Permalink to “选择键盘布局”">​</a></h5><p>接下来，你将必须设置键盘布局。对于大多数用户来说，默认设置的 “English (US)” 应该可以正常工作。</p><p>如果你要进行其他操作，则可以在继续之前测试你的键盘配置。</p><p><img src="https://itsfoss.com/content/images/2023/02/3.-select-Keyboard-layout-for-NixOS.png" alt="选择键盘格式"></p><p>之后，系统会要求你创建一个用户并为该用户设置密码。</p><p>你可以选择为虚拟机保留一个强密码或任何随机密码。</p><p><img src="https://itsfoss.com/content/images/2023/02/4.-create-user-and-set-password-for-NixOS.png" alt="创建用户"></p><h5 id="选择你喜欢的桌面环境" tabindex="-1">选择你喜欢的桌面环境 <a class="header-anchor" href="#选择你喜欢的桌面环境" aria-label="Permalink to “选择你喜欢的桌面环境”">​</a></h5><p>使用 NixOS，你可以选择以下桌面环境：</p><ul><li>GNOME</li><li>KDE（定制的最佳选择）</li><li>Xfce</li><li>Pantheon（ElementaryOS 附带的桌面环境）</li><li>Cinnamon</li><li>Enlightenment</li><li>LXQt</li></ul><p><img src="https://itsfoss.com/content/images/2023/02/5.-choose-desktop-environment-for-NixOS.png" alt="选择桌面环境"></p><h5 id="在-nixos-上使用非自由软件" tabindex="-1">在 NixOS 上使用非自由软件 <a class="header-anchor" href="#在-nixos-上使用非自由软件" aria-label="Permalink to “在 NixOS 上使用非自由软件”">​</a></h5><p>NixOS 遵循与 Fedora 类似的方法，你必须选择是否需要非自由软件。</p><p>我建议你启用非自由包：</p><p><img src="https://itsfoss.com/content/images/2023/02/6.-Allow-unfree-software.png" alt="启用非自由软件包"></p><h5 id="分区部分" tabindex="-1">分区部分 <a class="header-anchor" href="#分区部分" aria-label="Permalink to “分区部分”">​</a></h5><p>由于这是一个虚拟机指南，我建议你使用自动对磁盘进行分区的 “<ruby>擦除磁盘<rt>Erase disk</rt></ruby>” 选项！</p><p><img src="https://itsfoss.com/content/images/2023/02/7.-select-erase-disk-option-while-installing-NixOS.png" alt="自动分区"></p><p>完成后，它将为你提供你所做选择的摘要：</p><p><img src="https://itsfoss.com/content/images/2023/02/8.-summery-of-NixOS-installation-options-in-VM.png" alt="安装选择摘要"></p><p>如果一切正常，请单击 “<ruby>安装<rt>Install</rt></ruby>” 按钮，它将开始安装。</p><h5 id="不要重启而是关闭虚拟机" tabindex="-1">不要重启而是关闭虚拟机 <a class="header-anchor" href="#不要重启而是关闭虚拟机" aria-label="Permalink to “不要重启而是关闭虚拟机”">​</a></h5><p>安装完成后，你可以选择重新启动虚拟机。</p><p>如果你这样做，<strong>它将再次加载安装程序</strong>！</p><p>要解决此问题，你必须更改引导顺序。</p><p>为此，请在安装完成后关闭虚拟机。</p><p>要关闭虚拟机，请从“<ruby>文件<rt>File</rt></ruby>”菜单中选择 “<ruby>关闭<rt>Close</rt></ruby>” 选项，然后选择 “<ruby>关闭虚拟机电源<rt>Power off the machine</rt></ruby>” 选项：</p><p><img src="https://itsfoss.com/content/images/2023/02/poweroff-VM.png" alt=""></p><h5 id="更改-virtualbox-中的启动顺序" tabindex="-1">更改 VirtualBox 中的启动顺序 <a class="header-anchor" href="#更改-virtualbox-中的启动顺序" aria-label="Permalink to “更改 VirtualBox 中的启动顺序”">​</a></h5><p>要更改 NixOS 虚拟机 中的启动顺序，请打开该虚拟机的设置：</p><p><img src="https://itsfoss.com/content/images/2023/02/open-settings-for-VM-in-VirtualBox.png" alt=""></p><p>在设置中，选择 “<ruby>系统<rt>System</rt></ruby>”，你将找到启动顺序。</p><p>在这里，选择 “<ruby>硬盘<rt>Hard Disk</rt></ruby>” 并使用选项旁边的<strong>向上箭头</strong>图标并将其设为启动的第一个选项：</p><p><img src="https://itsfoss.com/content/images/2023/02/how-to-change-the-boot-order-in-VirtualBox.gif" alt="改变启动顺序"></p><p>按下 “<ruby>确定<rt>OK</rt></ruby>”，它将保存你所做的更改。</p><p><strong>或者</strong>，你可以移除我们添加的用于启动安装的光盘（ISO 镜像）。</p><h4 id="步骤-4-从-nixos-安装启动" tabindex="-1">步骤 4：从 NixOS 安装启动 <a class="header-anchor" href="#步骤-4-从-nixos-安装启动" aria-label="Permalink to “步骤 4：从 NixOS 安装启动”">​</a></h4><p>现在，启动你的 NixOS 虚拟机，你将看到一个 GRUB 屏幕：</p><p><img src="https://itsfoss.com/content/images/2023/02/NixOS-grub-screen.png" alt="NixOS grub"></p><p>选择默认选项，它将带你进入带有 GNOME 桌面的全新 NixOS 安装。</p><p><img src="https://itsfoss.com/content/images/2023/02/running-NixOS-in-VM.png" alt="运行 NixOS"></p><p>就是这些了！<strong>请继续探索 NixOS！</strong></p><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p>这是关于如何在 VirtualBox 上安装 NixOS 的快速指南。</p><p>对于 NixOS 教程系列的下一部分，我将分享有关<strong>安装和删除包</strong>的建议。</p><p>💬 <em>敬请期待本系列的下一部分。在那之前，请随时分享你对 NixOS 的看法或在遵循指南时遇到任何问题！</em></p><hr>',80)),s("p",null,[t[14]||(t[14]=i("via: ",-1)),a(r,{href:"https://itsfoss.com/install-nixos-vm/"},{default:n(()=>[...t[13]||(t[13]=[i("https://itsfoss.com/install-nixos-vm/",-1)])]),_:1})]),s("p",null,[t[19]||(t[19]=i("作者：",-1)),a(r,{href:"https://itsfoss.com/author/sagar/"},{default:n(()=>[...t[15]||(t[15]=[i("Sagar Sharma",-1)])]),_:1}),t[20]||(t[20]=i(" 选题：",-1)),a(r,{href:"https://github.com/lkxed/"},{default:n(()=>[...t[16]||(t[16]=[i("lkxed",-1)])]),_:1}),t[21]||(t[21]=i(" 译者：",-1)),a(r,{href:"https://github.com/geekpi"},{default:n(()=>[...t[17]||(t[17]=[i("geekpi",-1)])]),_:1}),t[22]||(t[22]=i(" 校对：",-1)),a(r,{href:"https://github.com/wxy"},{default:n(()=>[...t[18]||(t[18]=[i("wxy",-1)])]),_:1})]),s("p",null,[t[25]||(t[25]=i("本文由 ",-1)),a(r,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...t[23]||(t[23]=[i("LCTT",-1)])]),_:1}),t[26]||(t[26]=i(" 原创编译，",-1)),a(r,{href:"https://linux.cn/"},{default:n(()=>[...t[24]||(t[24]=[i("Linux中国",-1)])]),_:1}),t[27]||(t[27]=i(" 荣誉推出",-1))])])}const k=l(u,[["render",m]]);export{b as __pageData,k as default};
